package net.civeira.phylax.features.oauth.session.infrastructure.driver.rest;

import jakarta.enterprise.context.ApplicationScoped;
import net.civeira.phylax.features.oauth.oidc.domain.DiscoveryContributor;
import net.civeira.phylax.features.oauth.oidc.domain.OpenIdConfiguration;

/**
 * Contributes session-management endpoints and logout capability flags to the discovery document.
 */
@ApplicationScoped
public class SessionContributor implements DiscoveryContributor {

  @Override
  public void contribute(OpenIdConfiguration.OpenIdConfigurationBuilder builder, String base) {
    builder.endSessionEndpoint(base + "logout").checkSessionIframe(base + "login-status-iframe")
        .frontchannelLogoutSupported(true).frontchannelLogoutSessionSupported(true)
        .backchannelLogoutSupported(true).backchannelLogoutSessionSupported(true);
  }
}
